import { esc,fmt,dateLabel } from '../utils.js';
import { icon } from '../ui/icons.js';
import { button,empty } from '../ui/helpers.js';
import { newIdentity,profileCounts,validAvatar } from './model.js';
import { mealTotals } from '../meals/generator.js';

export function avatarMarkup(identity,{decorative=false}={}) {
  if(identity.avatar && validAvatar(identity.avatar))return `<img src="${identity.avatar}" alt="${decorative?'':esc('Foto de '+(identity.displayName||'perfil'))}" width="320" height="320">`;
  const initials=identity.displayName.trim().split(/\s+/).filter(Boolean).slice(0,2).map(n=>Array.from(n)[0]).join('').toLocaleUpperCase('es');
  return initials?`<span class="avatar-initials" aria-hidden="true">${esc(initials)}</span>`:icon('user');
}
export function profileView(state,profile,tab='activity') {
  const identity=state.identity||newIdentity(profile?.displayName||''),counts=profileCounts(state);
  const goal={lose:'Perder grasa',maintain:'Mantener peso',gain:'Ganar músculo'}[profile?.goal];
  const highlights=[['train','Entrenos','go-train'],['food','Menú','go-menu'],['progress','Progreso','go-progress'],['basket','Compra','go-shopping']];
  return `<section class="panel social-profile"><div class="profile-mobile-bar"><span>${esc(identity.handle||'mi.perfil')}</span><button type="button" class="secondary profile-cog" data-action="settings" aria-label="Abrir ajustes">${icon('settings')}</button></div><div class="social-profile-head"><button type="button" class="avatar-ring" data-action="edit-identity" aria-label="Cambiar mi foto de perfil"><span class="avatar-core">${avatarMarkup(identity,{decorative:true})}</span><i aria-hidden="true">${icon('plus')}</i></button><div class="social-profile-main"><div class="social-user-row"><h1>${identity.handle?'@'+esc(identity.handle):'Tu espacio personal'}</h1><span class="private-profile">${icon('lock')}Solo tú</span></div><dl class="social-counts" aria-label="Entrenamientos terminados, series con récord y registros de peso">${[['Entrenos',counts.workouts],['Récords',counts.records],['Pesajes',counts.weighIns]].map(([label,value])=>`<div><dt>${label}</dt><dd>${fmt(value)}</dd></div>`).join('')}</dl></div></div><div class="social-bio"><h2>${esc(identity.displayName||'Mi perfil')}</h2><span>Nutrición · Fuerza · Bienestar</span><p class="${identity.bio?'':'bio-placeholder'}">${esc(identity.bio||'Añade tu nombre y una biografía desde Editar perfil.')}</p>${goal?`<span class="social-goal">${icon('progress')}${esc(goal)}</span>`:''}</div><div class="social-profile-actions">${button('edit-identity','Editar perfil','','primary')}${button('edit-profile','Datos y objetivos')}</div></section><div class="profile-content-tabs" role="group" aria-label="Contenido de mi perfil">${[['activity','home','Actividad'],['records','trophy','Logros'],['saved','lock','Guardado']].map(([key,glyph,label])=>`<button type="button" data-action="profile-tab" data-tab="${key}" aria-pressed="${tab===key}">${icon(glyph)}<span>${label}</span></button>`).join('')}</div><section class="profile-content" aria-label="${{activity:'Mi actividad',records:'Mis logros',saved:'Comidas guardadas'}[tab]||'Mi actividad'}">${profileContent(state,tab)}</section>`;
}
function profileContent(state,tab) {
  const sessions=[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)||b.startedAt-a.startedAt);
  if(tab==='saved') {
    const locked=state.menu?.days.flatMap((day,d)=>day.meals.filter(m=>m.locked).map(meal=>({meal,day:day.date,index:d})))||[];
    if(!locked.length)return empty('Tus favoritos tienen su sitio','Las comidas que bloquees en el menú aparecerán aquí.',button('go-menu','Ir al menú'));
    return `<div class="profile-post-grid">${locked.map(({meal,day,index})=>`<button type="button" class="profile-post saved-post" data-action="profile-meal" data-day="${index}"><span class="post-symbol">${icon('food')}</span><span class="post-kind">${icon('lock')}Comida guardada</span><strong>${esc(meal.name)}</strong><span class="post-date">${esc(dateLabel(day))}</span><span class="post-data">${fmt(mealTotals(meal,state.foods).kcal)} kcal</span></button>`).join('')}</div>`;
  }
  if(tab==='records') {
    const records=sessions.flatMap(s=>s.sets.filter(x=>x.records?.length).map(set=>({session:s,set})));
    if(!records.length)return empty('Cada paso cuenta','Los récords que superes al entrenar quedarán guardados aquí.',button('go-train','Ir a entrenar'));
    return `<div class="profile-post-grid">${records.slice(0,30).map(({session,set})=>`<button type="button" class="profile-post record-post" data-action="view-session" data-id="${esc(session.id)}"><span class="post-symbol">${icon('trophy')}</span><span class="post-kind">${icon('trophy')}Récord personal</span><strong>${esc(state.exercises.find(e=>e.id===set.exerciseId)?.name||'Ejercicio')}</strong><span class="post-date">${esc(dateLabel(session.date))}</span><span class="post-data">${fmt(set.weight,1)} kg × ${set.reps}</span><small>${set.records.map(esc).join(' · ')}</small></button>`).join('')}</div><p class="profile-grid-note">Se muestran las 30 series con récord más recientes.</p>`;
  }
  if(!sessions.length)return empty('Tu historia empieza contigo','Cuando termines un entrenamiento, aparecerá en tu cuadrícula.',button('go-train','Empezar a entrenar'));
  return `<div class="profile-post-grid">${sessions.slice(0,30).map(s=>`<button type="button" class="profile-post activity-post" data-action="view-session" data-id="${esc(s.id)}"><span class="post-symbol">${icon('train')}</span><span class="post-kind">${icon('train')}Entrenamiento</span><strong>${esc(s.name)}</strong><span class="post-date">${esc(dateLabel(s.date))}</span><span class="post-data">${s.sets.length} series</span></button>`).join('')}</div><p class="profile-grid-note">Tus 30 entrenamientos más recientes. El historial completo está en Entrenar.</p>`;
}
export function identityForm(identity) {
  return `<form data-form="identity"><h2>Editar perfil</h2><div class="identity-photo-row"><div id="identity-photo-preview" class="avatar-core">${avatarMarkup(identity,{decorative:true})}</div><div><label class="file-label">${icon('plus')}Cambiar foto<input type="file" id="identity-photo" accept="image/jpeg,image/png,image/webp" aria-label="Elegir foto de perfil"></label>${button('remove-avatar','Quitar foto')}</div></div><p class="help" id="photo-status">JPG, PNG o WebP hasta 8 MB. Recorte cuadrado automático, guardado solo en este dispositivo.</p><label>Nombre<input name="displayName" maxlength="60" autocomplete="given-name" value="${esc(identity.displayName)}" placeholder="Cómo quieres que te llamemos"></label><label>Usuario<input name="handle" maxlength="31" autocomplete="off" autocapitalize="none" spellcheck="false" value="${esc(identity.handle)}" placeholder="tu.usuario"><small>Hasta 30 caracteres: letras, números, puntos y guion bajo. Es un alias local; no crea una cuenta.</small></label><label>Biografía<textarea name="bio" maxlength="160" rows="3" placeholder="Un poco sobre ti y lo que te mueve…">${esc(identity.bio)}</textarea><small>Hasta 160 caracteres.</small></label><button class="primary" id="identity-save">Guardar perfil</button></form>`;
}
export function sessionDetail(state,session) {
  return `<div class="profile-session-detail"><p class="eyebrow">${esc(dateLabel(session.date))}</p><h2>${esc(session.name)}</h2><p class="help">${session.sets.length} series registradas</p><ul>${session.sets.map(set=>`<li><strong>${esc(state.exercises.find(e=>e.id===set.exerciseId)?.name||'Ejercicio')}</strong><span>${fmt(set.weight,1)} kg × ${set.reps}${set.rpe===null?'':' · RPE '+fmt(set.rpe,1)}</span>${set.records?.length?`<small>${icon('trophy')}${set.records.map(esc).join(' · ')}</small>`:''}</li>`).join('')}</ul>${session.notes?`<p class="note">${esc(session.notes)}</p>`:''}</div>`;
}
